"""Unit tests for API key loading and LLM merge guardrails."""

import asyncio
import sys
import tempfile
import unittest
from unittest.mock import patch

PY310_PLUS = sys.version_info >= (3, 10)

if PY310_PLUS:
    from nvidia_resiliency_ext.attribution.api_keys import (
        DEFAULT_LLM_API_KEY_PATHS,
        llm_api_key_help_text,
        llm_api_key_missing_message,
        load_llm_api_key,
    )
    from nvidia_resiliency_ext.attribution.legacy_logsage.combined_log_fr.llm_merge import (
        merge_log_fr_llm,
    )
    from nvidia_resiliency_ext.attribution.orchestration.config import DEFAULT_LLM_BASE_URL


@unittest.skipUnless(
    PY310_PLUS,
    "Attribution package requires Python 3.10+ (e.g. dataclass(slots=True) in svc.job).",
)
class TestLoadLlmApiKey(unittest.TestCase):
    def test_reads_and_strips_llm_env(self):
        with patch.dict("os.environ", {"LLM_API_KEY": "  sk-test  "}):
            self.assertEqual(load_llm_api_key(), "sk-test")

    def test_returns_empty_when_unset_and_no_key_files(self):
        def getenv_side_effect(key: str, default=None):
            if key in ("LLM_API_KEY", "LLM_API_KEY_FILE"):
                return None
            return default

        with (
            patch(
                "nvidia_resiliency_ext.attribution.api_keys.os.getenv",
                side_effect=getenv_side_effect,
            ),
            patch("nvidia_resiliency_ext.attribution.api_keys.os.path.isfile", return_value=False),
        ):
            self.assertEqual(load_llm_api_key(), "")

    def test_llm_api_key_file_used_when_set(self):
        with tempfile.NamedTemporaryFile(mode="w", delete=False, suffix=".key") as f:
            f.write("key-from-file\n")
            path = f.name
        try:
            with patch.dict("os.environ", {"LLM_API_KEY_FILE": path}, clear=True):
                self.assertEqual(load_llm_api_key(), "key-from-file")
        finally:
            import os as _os

            _os.unlink(path)

    def test_llm_api_key_message_mentions_all_sources(self):
        help_text = llm_api_key_help_text()
        message = llm_api_key_missing_message(include_empty=True, context="Context.")

        self.assertIn("LLM_API_KEY", help_text)
        self.assertIn("LLM_API_KEY_FILE", help_text)
        for path in DEFAULT_LLM_API_KEY_PATHS:
            self.assertIn(path, help_text)
            self.assertIn(path, message)
        self.assertIn("not found or empty", message)
        self.assertIn("Context.", message)


@unittest.skipUnless(
    PY310_PLUS,
    "Attribution package requires Python 3.10+ (e.g. dataclass(slots=True) in svc.job).",
)
class TestMergeLogFrLlm(unittest.TestCase):
    def test_raises_when_api_key_empty(self):
        async def run():
            with self.assertRaises(ValueError) as ctx:
                await merge_log_fr_llm(
                    "log",
                    "fr",
                    llm_api_key="",
                    model="dummy-model",
                    base_url=DEFAULT_LLM_BASE_URL,
                )
            self.assertIn("LLM API key", str(ctx.exception))

        asyncio.run(run())


if __name__ == "__main__":
    unittest.main()

import pytest

from nvidia_resiliency_ext.attribution.orchestration.llm_output import (
    fr_only_no_log_payload,
    logsage_recommendation,
    logsage_recommendation_from_payload,
    logsage_timeout_payload,
    recommendation_payload,
)


def _item(raw_text, action):
    return {
        "raw_text": raw_text,
        "auto_resume": raw_text.split("\n", 1)[0],
        "auto_resume_explanation": "",
        "attribution_text": "",
        "checkpoint_saved_flag": 0,
        "action": action,
        "primary_issues": [],
        "secondary_issues": [],
    }


def test_logsage_recommendation_derives_restart_from_structured_item():
    recommendation = logsage_recommendation(
        [_item("RESTART IMMEDIATE\ntransient timeout", "RESTART")],
        source="log_analyzer",
    )

    assert recommendation.action == "RESTART"
    assert recommendation.reason == "RESTART IMMEDIATE\ntransient timeout"
    assert recommendation.source == "log_analyzer"


def test_logsage_recommendation_uses_highest_priority_cycle_action():
    recommendation = logsage_recommendation(
        [
            _item("ERRORS NOT FOUND", "CONTINUE"),
            _item("STOP - DONT RESTART IMMEDIATE\nuser error", "STOP"),
        ],
        source="log_analyzer",
    )

    assert recommendation.action == "STOP"
    assert recommendation.reason == "STOP - DONT RESTART IMMEDIATE\nuser error"
    assert recommendation.source == "log_analyzer"


def test_logsage_recommendation_from_payload_maps_timeout():
    payload = logsage_timeout_payload("LLM analysis timed out")
    recommendation = logsage_recommendation_from_payload(
        payload,
    )

    assert payload == {
        "module": "log_analyzer",
        "state": "timeout",
        "result": [],
        "error": "LLM analysis timed out",
        "recommendation": {
            "action": "TIMEOUT",
            "source": "log_analyzer",
        },
    }
    assert recommendation.action == "TIMEOUT"
    assert recommendation.reason == "LLM analysis timed out"
    assert recommendation.source == "log_analyzer"


def test_logsage_recommendation_from_payload_maps_fr_only_no_log():
    payload = fr_only_no_log_payload()
    recommendation = logsage_recommendation_from_payload(payload)

    assert payload == {
        "module": "fr_only",
        "state": "no_log",
        "result": [],
        "recommendation": {
            "action": "UNKNOWN",
            "source": "fr_only",
        },
    }
    assert recommendation.action == "UNKNOWN"
    assert recommendation.reason == "no_log"
    assert recommendation.source == "fr_only"


def test_logsage_recommendation_from_payload_uses_module_as_source_fallback():
    recommendation = logsage_recommendation_from_payload(
        {
            "module": "log_analyzer",
            "recommendation": {
                "action": "STOP",
                "reason": "terminal issue",
            },
            "result": [],
        }
    )

    assert recommendation.action == "STOP"
    assert recommendation.reason == "terminal issue"
    assert recommendation.source == "log_analyzer"


def test_logsage_recommendation_from_payload_does_not_rederive_from_result_items():
    recommendation = logsage_recommendation_from_payload(
        {
            "module": "log_analyzer",
            "result": [_item("STOP - DONT RESTART IMMEDIATE\nuser error", "STOP")],
        }
    )

    assert recommendation.action == "UNKNOWN"
    assert recommendation.reason == ""
    assert recommendation.source == "log_analyzer"


def test_recommendation_payload_keeps_public_contract_action_source_only():
    recommendation = logsage_recommendation(
        [_item("STOP - DONT RESTART IMMEDIATE\nuser error", "STOP")],
        source="log_analyzer",
    )

    assert recommendation_payload(recommendation) == {
        "action": "STOP",
        "source": "log_analyzer",
    }


def test_logsage_recommendation_rejects_unstructured_items():
    with pytest.raises(TypeError):
        logsage_recommendation(["STOP - DONT RESTART"], source="log_analyzer")

